<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefc;
      --muted: #9aa8c7;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --error: #fda4af;
      --error-strong: #fb7185;
      --input: rgba(15, 23, 42, 0.9);
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 28%),
        linear-gradient(180deg, #0f172a 0%, #020617 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 520px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    h1 {
      margin: 0 0 10px;
      font-size: 1.9rem;
    }

    .intro {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.5;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 700;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: 12px;
      background: var(--input);
      color: var(--text);
      font: inherit;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #6b7a99;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.18);
    }

    input[aria-invalid="true"] {
      border-color: var(--error-strong);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.16);
    }

    .helper-text,
    .error-message,
    .status-message {
      margin: 0;
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      min-height: 1.3em;
      color: var(--error);
    }

    .status-message {
      min-height: 1.4em;
      color: #86efac;
    }

    button {
      border: 0;
      border-radius: 12px;
      padding: 14px 18px;
      font: inherit;
      font-weight: 700;
      color: white;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
      box-shadow: 0 16px 30px rgba(59, 130, 246, 0.26);
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    @media (max-width: 480px) {
      .support-card {
        padding: 24px;
      }
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact support</h1>
    <p class="intro">Need help with your account or service? Send us your details and our support team will follow up.</p>

    <form id="supportForm" novalidate>
      <div class="form-field">
        <label for="fullName">Full name</label>
        <input
          id="fullName"
          name="fullName"
          type="text"
          autocomplete="name"
          placeholder="Jordan Lee"
          required
          aria-describedby="fullNameError"
        >
        <p id="fullNameError" class="error-message" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input
          id="email"
          name="email"
          type="email"
          autocomplete="email"
          placeholder="jordan@example.com"
          required
          aria-describedby="emailError"
        >
        <p id="emailError" class="error-message" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          placeholder="(555) 123-4567"
          aria-describedby="phoneHelp phoneError"
        >
        <p id="phoneHelp" class="helper-text">Optional. Use a format like (555) 123-4567 or +1 555 123 4567.</p>
        <p id="phoneError" class="error-message" aria-live="polite"></p>
      </div>

      <button type="submit">Submit</button>
      <p id="formStatus" class="status-message" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("supportForm");
    const fields = {
      fullName: {
        input: document.getElementById("fullName"),
        error: document.getElementById("fullNameError"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }

          if (value.trim().length < 2) {
            return "Enter your full name.";
          }

          return "";
        }
      },
      email: {
        input: document.getElementById("email"),
        error: document.getElementById("emailError"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }

          return "";
        }
      },
      phone: {
        input: document.getElementById("phone"),
        error: document.getElementById("phoneError"),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return "";
          }

          const phonePattern = /^\+?[\d\s().-]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return "Enter a valid phone number using the suggested format.";
          }

          return "";
        }
      }
    };

    const formStatus = document.getElementById("formStatus");

    function validateField(fieldConfig) {
      const message = fieldConfig.validate(fieldConfig.input.value);
      fieldConfig.error.textContent = message;
      fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
      return !message;
    }

    Object.values(fields).forEach((fieldConfig) => {
      fieldConfig.input.addEventListener("input", () => {
        validateField(fieldConfig);
        formStatus.textContent = "";
      });

      fieldConfig.input.addEventListener("blur", () => {
        validateField(fieldConfig);
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = Object.values(fields).every((fieldConfig) => validateField(fieldConfig));

      if (!isValid) {
        formStatus.textContent = "";
        const firstInvalid = Object.values(fields).find((fieldConfig) => fieldConfig.input.getAttribute("aria-invalid") === "true");
        if (firstInvalid) {
          firstInvalid.input.focus();
        }
        return;
      }

      formStatus.textContent = "Your support request is ready to send.";
      form.reset();

      Object.values(fields).forEach((fieldConfig) => {
        fieldConfig.error.textContent = "";
        fieldConfig.input.setAttribute("aria-invalid", "false");
      });
    });
  </script>
</body>
</html>
